import{_ as i,C as n,o,c as r,j as a,a as s,G as l,a3 as h}from"./chunks/framework.Bvm_liKL.js";const b=JSON.parse('{"title":"Features Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/overview.md","filePath":"en/features/overview.md"}'),d={name:"en/features/overview.md"};function c(u,e,p,g,m,f){const t=n("ArticleMetadata");return o(),r("div",null,[e[0]||(e[0]=a("h1",{id:"features-overview",tabindex:"-1"},[s("Features Overview "),a("a",{class:"header-anchor",href:"#features-overview","aria-label":'Permalink to "Features Overview"'},"​")],-1)),l(t),e[1]||(e[1]=h('<h2 id="smart-ink-processing" tabindex="-1">Smart Ink Processing <a class="header-anchor" href="#smart-ink-processing" aria-label="Permalink to &quot;Smart Ink Processing&quot;">​</a></h2><h3 id="straight-line-correction" tabindex="-1">Straight Line Correction <a class="header-anchor" href="#straight-line-correction" aria-label="Permalink to &quot;Straight Line Correction&quot;">​</a></h3><p>When drawing strokes close to a straight line, ICC-CE can automatically identify and convert them into perfect straight lines. You can adjust the sensitivity and threshold in the settings:</p><ul><li><strong>Sensitivity setting</strong>: Controls the threshold for line straightness detection, ranging from 0.05 to 2.0.</li><li><strong>Length threshold</strong>: Only lines exceeding the set length will be considered for straightening.</li></ul><h3 id="shape-recognition" tabindex="-1">Shape Recognition <a class="header-anchor" href="#shape-recognition" aria-label="Permalink to &quot;Shape Recognition&quot;">​</a></h3><p>Automatically recognizes and optimizes hand-drawn shapes, including:</p><ul><li>Rectangles and Squares</li><li>Triangles</li><li>Circles and Ellipses</li></ul><h3 id="endpoint-snapping" tabindex="-1">Endpoint Snapping <a class="header-anchor" href="#endpoint-snapping" aria-label="Permalink to &quot;Endpoint Snapping&quot;">​</a></h3><p>When drawing lines, endpoints will automatically snap to other endpoints nearby, making it easier to create well-connected geometric drawings.</p><h2 id="diverse-drawing-tools" tabindex="-1">Diverse Drawing Tools <a class="header-anchor" href="#diverse-drawing-tools" aria-label="Permalink to &quot;Diverse Drawing Tools&quot;">​</a></h2><h3 id="pen-and-highlighter" tabindex="-1">Pen and Highlighter <a class="header-anchor" href="#pen-and-highlighter" aria-label="Permalink to &quot;Pen and Highlighter&quot;">​</a></h3><ul><li>Adjustable brush thickness and opacity.</li><li>A rich selection of preset colors.</li><li>Pen pressure sensitivity support (for devices supporting pressure levels).</li></ul><h3 id="touch-modes" tabindex="-1">Touch Modes <a class="header-anchor" href="#touch-modes" aria-label="Permalink to &quot;Touch Modes&quot;">​</a></h3><ul><li>Finger Drawing: Draw directly using touch screens.</li><li>Nib Mode: A high-precision drawing mode specifically designed for active styluses.</li><li>Simulated Pressure: Simulates pressure effects on devices that do not support hardware pressure sensitivity.</li></ul><h3 id="eraser" tabindex="-1">Eraser <a class="header-anchor" href="#eraser" aria-label="Permalink to &quot;Eraser&quot;">​</a></h3><ul><li>Point Erasing: Precisely erase parts of ink strokes.</li><li>Stroke Erasing: Erase the entire stroke at once.</li><li>Adjustable eraser size and shape.</li></ul><h2 id="powerpoint-integration" tabindex="-1">PowerPoint Integration <a class="header-anchor" href="#powerpoint-integration" aria-label="Permalink to &quot;PowerPoint Integration&quot;">​</a></h2><h3 id="presentation-enhancements" tabindex="-1">Presentation Enhancements <a class="header-anchor" href="#presentation-enhancements" aria-label="Permalink to &quot;Presentation Enhancements&quot;">​</a></h3><ul><li>Annotate directly in slideshow/presentation mode.</li><li>Customizable control buttons for easy slideshow navigation.</li><li>Save slideshow screenshots containing annotations.</li></ul><h3 id="gesture-control" tabindex="-1">Gesture Control <a class="header-anchor" href="#gesture-control" aria-label="Permalink to &quot;Gesture Control&quot;">​</a></h3><ul><li>Control slide switching using hand gestures.</li><li>Zoom and pan annotated contents.</li><li>Rotate and rearrange drawn elements.</li></ul><h2 id="multi-touch-support" tabindex="-1">Multi-touch Support <a class="header-anchor" href="#multi-touch-support" aria-label="Permalink to &quot;Multi-touch Support&quot;">​</a></h2><ul><li>Two-finger Zoom: Zoom in or out of the drawing canvas.</li><li>Rotate Gesture: Rotate the selected elements.</li><li>Panning Operation: Move around the drawing canvas.</li></ul><h2 id="automation-features" tabindex="-1">Automation Features <a class="header-anchor" href="#automation-features" aria-label="Permalink to &quot;Automation Features&quot;">​</a></h2><h3 id="auto-detection" tabindex="-1">Auto Detection <a class="header-anchor" href="#auto-detection" aria-label="Permalink to &quot;Auto Detection&quot;">​</a></h3><ul><li>Detect common whiteboard and teaching applications.</li><li>Adaptive interface behavior to avoid blocking other apps.</li><li>Optimize performance under different software environments.</li></ul><h3 id="auto-save" tabindex="-1">Auto Save <a class="header-anchor" href="#auto-save" aria-label="Permalink to &quot;Auto Save&quot;">​</a></h3><ul><li>Save drawing contents at regular intervals.</li><li>Automatically back up the canvas before clearing it.</li><li>Organize screenshots and ink files inside date folders.</li></ul><h2 id="ui-customization" tabindex="-1">UI Customization <a class="header-anchor" href="#ui-customization" aria-label="Permalink to &quot;UI Customization&quot;">​</a></h2><ul><li>Adjust toolbar opacity and scale.</li><li>Multiple icon style options.</li><li>Whiteboard mode UI scaling.</li><li>Quick panel and side-docking mode.</li></ul>',30))])}const w=i(d,[["render",c]]);export{b as __pageData,w as default};
